WITH with_window AS (SELECT e.*, pr.id AS promo_id, pr.promo_code AS promotion_promo_code, pr.discount_pct AS promotion_discount_pct FROM promotions e LEFT JOIN promotions pr ON e.channel = pr.channel AND e.ends_on >= pr.starts_on AND e.ends_on < pr.ends_on + INTERVAL 7 DAYS) SELECT CASE WHEN discount_pct >= 0.33 THEN 'PREMIUM' ELSE 'STANDARD' END AS discount_pct_tier, channel, APPROX_PERCENTILE(promotion_discount_pct, 0.95) AS promotion_discount_pct_p95, SORT_ARRAY(COLLECT_SET(channel)) AS channel_list, GROUPING_ID() AS gid FROM with_window GROUP BY GROUPING SETS ((CASE WHEN discount_pct >= 0.33 THEN 'PREMIUM' ELSE 'STANDARD' END, channel), (CASE WHEN discount_pct >= 0.33 THEN 'PREMIUM' ELSE 'STANDARD' END), ()) HAVING APPROX_PERCENTILE(promotion_discount_pct, 0.95) > 0 ORDER BY promotion_discount_pct_p95;
